package communityplus
import ("context"; "fmt"; "github.com/fleetdm/fleet/v4/server/fleet")
var OrbitDelivery *SQLStore
func PendingOrbitDeployments(ctx context.Context, host *fleet.Host) ([]string,error) { if OrbitDelivery==nil||host==nil||host.TeamID==nil||host.Platform!="windows"{return nil,nil}; return OrbitDelivery.PendingDeploymentIDs(ctx,host.ID,*host.TeamID) }
func OrbitWindowsPlan(ctx context.Context, host *fleet.Host, id string)(*fleet.CommunityPlusWindowsInstallPlan,error){if OrbitDelivery==nil||host==nil||host.TeamID==nil||host.Platform!="windows"{return nil,fmt.Errorf("Community+ deployment is unavailable for this host")};d,err:=OrbitDelivery.GetDeployment(ctx,id);if err!=nil{return nil,err};if !d.Automatic||d.Scope.FleetID!=*host.TeamID{return nil,fmt.Errorf("Community+ deployment is not assigned to this host")};e,err:=OrbitDelivery.GetCatalogEntry(ctx,d.CatalogEntryID);if err!=nil{return nil,err};p,err:=NewWindowsInstallPlan(d,e);if err!=nil{return nil,err};return &fleet.CommunityPlusWindowsInstallPlan{DeploymentID:p.DeploymentID,PackageID:p.PackageID,Version:p.Version,InstallerURL:p.InstallerURL,SHA256:p.SHA256,InstallerType:p.InstallerType,ProductCode:p.ProductCode},nil}
func RecordOrbitDeploymentResult(ctx context.Context,host *fleet.Host,result *fleet.CommunityPlusDeploymentResult)error{if OrbitDelivery==nil||host==nil||result==nil{return fmt.Errorf("Community+ deployment result is unavailable")};d,err:=OrbitDelivery.GetDeployment(ctx,result.DeploymentID);if err!=nil{return err};if host.TeamID==nil||d.Scope.FleetID!=*host.TeamID{return fmt.Errorf("Community+ deployment is not assigned to this host")};return OrbitDelivery.RecordDeploymentResult(ctx,host.ID,*result)}
